-- Guest Hub H6c «الفريق والتقارير» (15 Nov 2026, Ahmed — DECISIONS.md 2026-11-15 «Guest Hub H6c — the team and the reports»).
-- Generated by scripts/hub-team-migration.mjs from scripts/hub-team-migration.src.sql and the latest definitions of the
-- functions it replaces — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   1. The section «الفريق والتقارير» (hub_team: view / edit, branch scope; the reports tab is the system admin's).
--   2. «فريق الاستقبال»: up to 5 staff slots per branch (name, WhatsApp number, role, days and hours — overnight allowed,
--      «نشط», «يُعامَل كضيف للتجربة», the staff member's consent), and per branch «عودة المساعد بعد صمت الفريق» (15) and
--      «تصعيد إذا لم تُفتح المحادثة خلال» (10).
--   3. «التقارير»: up to 3 recipients, the send time (08:00 Riyadh), the daily report hub_daily_report from the Airport Road
--      number about the previous day (+ the email archive to the hub_summary recipients), «إرسال تجربة لي».
--   4. Staff alerts on WhatsApp (hub_staff_alert): every new hand-off → the on-shift slots of the branch from the branch's
--      own number (nobody on shift → the managers; no slot → email only); one per waiting hand-off; escalation to the
--      managers not yet alerted after the branch's minutes; tracked: sent, delivered, opened, first staff reply.
--   5. Hand-off ownership: «بانتظار موظف» (handed, no staff reply — the assistant keeps answering what it can; a second
--      thing it cannot answer is added to the same hand-off) and «مع موظف» (a staff reply — the assistant is silent, and
--      resumes by itself when the guest writes after the branch's «عودة المساعد» minutes of staff silence).
--   6. Staff and management numbers are never guests (no episode, no marketing, no review or departure message) unless
--      «يُعامَل كضيف للتجربة» is on; their messages get the colleague chat (wa-automation).
-- No unit mode, licence or global switch changes. No phone number in this file.

-- ───────────────────────────────────────────── 1. the section ─────────────────────────────────────────────
insert into public.sections (key, label_ar, sort, editable, presets, max_level) values
  ('hub_team', 'الفريق والتقارير', 59, true, '{"admin": "edit", "management": "edit", "sales": "none", "reception": "view"}', 'edit')
on conflict (key) do nothing;
insert into public.staff_permissions (user_id, section, level)
select s.user_id, x.key, (x.presets ->> s.role::text)::public.perm_level
  from public.staff s cross join public.sections x where x.key = 'hub_team'
on conflict do nothing;

-- ───────────────────────────────────────────── 2. columns ─────────────────────────────────────────────
-- the last staff action (an inbox send, a phone reply, a take-over): «عودة المساعد» counts from it
alter table public.hub_conversations add column staff_active_at timestamptz;
-- the waiting hand-off of the conversation (its staff alert), set by the trigger below
alter table public.hub_conversations add column handoff_id uuid;
-- the template's body as YCloud stores it: a template whose body differs from templates.md is never sent
alter table public.hub_templates add column body text check (body is null or char_length(body) <= 2000);
alter table public.hub_usage_daily drop constraint hub_usage_daily_layer_check;
alter table public.hub_usage_daily add constraint hub_usage_daily_layer_check check (layer in ('understand', 'tag', 'compose', 'translate', 'suggest', 'draft_card', 'summary', 'staff_chat'));

-- ───────────────────────────────────────────── 3. tables ─────────────────────────────────────────────
create table public.hub_staff_slots (
  id uuid primary key default gen_random_uuid(),
  branch_slug text not null references public.branches (slug) on update cascade,
  position smallint not null check (position between 1 and 5),
  name text not null check (char_length(btrim(name)) between 2 and 60),
  phone text not null check (phone ~ '^\+[1-9][0-9]{7,14}$'),
  role text not null check (role in ('manager', 'staff')),
  -- 0 = Sunday … 6 = Saturday (Riyadh); an overnight shift (start > end) belongs to the day it starts
  days smallint[] not null default '{0,1,2,3,4,5,6}' check (days <@ '{0,1,2,3,4,5,6}'::smallint[]),
  start_time time not null,
  end_time time not null,
  active boolean not null default true,
  test_as_guest boolean not null default false,
  consent_at timestamptz not null,
  consent_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint hub_staff_slots_hours check (start_time <> end_time),
  unique (branch_slug, position),
  unique (branch_slug, phone)
);
comment on table public.hub_staff_slots is '«الفريق والتقارير» → «فريق الاستقبال» (15 Nov 2026, H6c): up to 5 reception staff per branch who get the hand-off alerts on WhatsApp during their hours. Written only by hub_staff_slot_save / _delete.';
create trigger hub_staff_slots_touch before update on public.hub_staff_slots for each row execute function internal.stamp();
alter table public.hub_staff_slots enable row level security;

create table public.hub_team_branches (
  branch_slug text primary key references public.branches (slug) on update cascade,
  resume_minutes integer not null default 15 check (resume_minutes between 5 and 240),
  escalate_minutes integer not null default 10 check (escalate_minutes between 2 and 120),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);
comment on table public.hub_team_branches is '«الفريق والتقارير»: per branch «عودة المساعد بعد صمت الفريق (دقائق)» and «تصعيد إذا لم تُفتح المحادثة خلال (دقائق)».';
insert into public.hub_team_branches (branch_slug) select slug from public.branches where slug in ('airport-road', 'shafa-road') on conflict do nothing;
alter table public.hub_team_branches enable row level security;

create table public.hub_report_recipients (
  id uuid primary key default gen_random_uuid(),
  position smallint not null unique check (position between 1 and 3),
  name text not null check (char_length(btrim(name)) between 2 and 60),
  phone text not null unique check (phone ~ '^\+[1-9][0-9]{7,14}$'),
  -- the dashboard user this number belongs to («إرسال تجربة لي» sends to it)
  staff_user_id uuid references auth.users (id) on delete set null,
  active boolean not null default true,
  test_as_guest boolean not null default false,
  consent_at timestamptz not null,
  consent_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table public.hub_report_recipients is '«الفريق والتقارير» → «التقارير»: up to 3 numbers that get the daily report hub_daily_report. The system admin only.';
create trigger hub_report_recipients_touch before update on public.hub_report_recipients for each row execute function internal.stamp();
alter table public.hub_report_recipients enable row level security;

create table public.hub_report_config (
  id boolean primary key default true check (id),
  send_time time not null default '08:00',
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);
insert into public.hub_report_config (id) values (true) on conflict do nothing;
alter table public.hub_report_config enable row level security;

create table public.hub_handoffs (
  id uuid primary key,
  conversation_id uuid not null references public.hub_conversations (id) on delete cascade,
  unit_id uuid not null references public.hub_units (id) on delete cascade,
  branch_slug text not null,
  reason text check (reason is null or reason ~ '^[a-z_]{2,40}$'),
  -- {{5}}: one line written by the model at the hand-off (≤ 120, nothing invented) — cleared after 30 days
  summary text check (summary is null or char_length(summary) <= 120),
  -- {{4}}: the booking ref or the room the guest gave
  ref_text text check (ref_text is null or char_length(ref_text) <= 40),
  additions integer not null default 0 check (additions >= 0),
  token text not null unique default replace(gen_random_uuid()::text, '-', ''),
  status text not null default 'pending' check (status in ('pending', 'alerted', 'email_only')),
  alerted_at timestamptz,
  escalated_at timestamptz,
  opened_at timestamptz,
  opened_by uuid references auth.users (id) on delete set null,
  opened_via text check (opened_via is null or opened_via in ('link', 'inbox')),
  first_reply_at timestamptz,
  closed_at timestamptz,
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
comment on table public.hub_handoffs is 'Guest Hub (H6c): one row per hand-off to the team — its staff alert, escalation and tracking (sent, delivered, opened, first staff reply). No guest words, no phone.';
create index hub_handoffs_open on public.hub_handoffs (created_at) where closed_at is null;
create index hub_handoffs_conversation on public.hub_handoffs (conversation_id);
alter table public.hub_handoffs enable row level security;

create table public.hub_staff_sends (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('alert', 'escalation', 'report', 'report_test')),
  handoff_id uuid references public.hub_handoffs (id) on delete cascade,
  report_day date,
  slot_id uuid references public.hub_staff_slots (id) on delete set null,
  recipient_id uuid references public.hub_report_recipients (id) on delete set null,
  channel_id uuid references public.hub_channels (id) on delete set null,
  template text not null check (template in ('hub_staff_alert', 'hub_daily_report')),
  -- report_test: the figures of the day so far (counts only)
  payload jsonb,
  status text not null default 'queued' check (status in ('queued', 'pending', 'accepted', 'sent', 'delivered', 'read', 'failed', 'skipped', 'test')),
  provider_message_id text,
  error_code text check (error_code is null or char_length(error_code) <= 40),
  price numeric,
  currency text,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint hub_staff_sends_target check ((kind in ('alert', 'escalation')) = (handoff_id is not null))
);
comment on table public.hub_staff_sends is 'Guest Hub (H6c): each staff alert and daily report sent on WhatsApp — the slot or recipient, never the number or a text; YCloud''s statuses (wa_status_update).';
-- one alert per waiting hand-off and slot (an escalation never repeats an alerted manager); one report per day and recipient
create unique index hub_staff_sends_handoff_slot on public.hub_staff_sends (handoff_id, slot_id) where handoff_id is not null and slot_id is not null;
create unique index hub_staff_sends_report on public.hub_staff_sends (report_day, recipient_id) where kind = 'report';
create index hub_staff_sends_queued on public.hub_staff_sends (created_at) where status = 'queued';
create index hub_staff_sends_provider on public.hub_staff_sends (provider_message_id) where provider_message_id is not null;
alter table public.hub_staff_sends enable row level security;

create table public.hub_daily_reports (
  day date primary key,
  data jsonb not null,
  built_at timestamptz not null default now(),
  emailed_at timestamptz
);
comment on table public.hub_daily_reports is 'Guest Hub (H6c): the daily report of each day (counts only, never money) — the WhatsApp report, its email archive and ?hub_r= read the same figures.';
alter table public.hub_daily_reports enable row level security;

-- the colleague chat of a staff or report number (H6c): kept 30 days for the conversation's context; never shown in the inbox
create table public.hub_staff_messages (
  id uuid primary key default gen_random_uuid(),
  who_kind text not null check (who_kind in ('staff', 'report')),
  who_id uuid not null,
  channel_id uuid references public.hub_channels (id) on delete set null,
  direction text not null check (direction in ('in', 'out')),
  body text check (body is null or char_length(body) <= 4096),
  provider_message_id text unique,
  status text not null default 'received' check (status in ('received', 'queued', 'accepted', 'sent', 'delivered', 'read', 'failed', 'skipped', 'test')),
  error_code text check (error_code is null or char_length(error_code) <= 40),
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
create index hub_staff_messages_who on public.hub_staff_messages (who_id, created_at desc);
alter table public.hub_staff_messages enable row level security;

create trigger hub_staff_slots_audit after insert or update or delete on public.hub_staff_slots
  for each row execute function internal.audit('branch_slug', 'position', 'name', 'role', 'days', 'start_time', 'end_time', 'active', 'test_as_guest', 'consent_at');
create trigger hub_team_branches_audit after insert or update or delete on public.hub_team_branches
  for each row execute function internal.audit('branch_slug', 'resume_minutes', 'escalate_minutes');
create trigger hub_report_recipients_audit after insert or update or delete on public.hub_report_recipients
  for each row execute function internal.audit('position', 'name', 'staff_user_id', 'active', 'test_as_guest', 'consent_at');
create trigger hub_report_config_audit after insert or update or delete on public.hub_report_config
  for each row execute function internal.audit('send_time');

-- ───────────────────────────────────────────── 4. helpers ─────────────────────────────────────────────
-- a slot is on shift at this moment (Riyadh): the day the shift starts is one of its days; an overnight shift runs into
-- the next morning (23:00–07:00 on Sunday covers Monday 03:00)
create function internal.hub_slot_covers(s public.hub_staff_slots, p_at timestamptz default now()) returns boolean
language sql stable set search_path = '' as $$
  select case when s.start_time < s.end_time
              then extract(dow from l)::smallint = any (s.days) and l::time >= s.start_time and l::time < s.end_time
              else (extract(dow from l)::smallint = any (s.days) and l::time >= s.start_time)
                or (extract(dow from (l - interval '1 day'))::smallint = any (s.days) and l::time < s.end_time) end
    from (select (p_at at time zone 'Asia/Riyadh') as l) t
$$;

-- a number in a staff slot or the report list: who it is; null for everyone else. A number in both is staff.
create function internal.hub_staff_lookup(p_phone text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select case when count(*) = 0 then null else jsonb_build_object(
           'kind', case when bool_or(x.k = 'staff') then 'staff' else 'report' end,
           'test_as_guest', bool_or(x.test_as_guest),
           'name', (array_agg(x.name order by x.k desc, x.pos))[1],
           'who_id', (array_agg(x.id order by x.k desc, x.pos))[1],
           'role', (array_agg(x.role order by x.k desc, x.pos) filter (where x.k = 'staff'))[1],
           'branches', coalesce(jsonb_agg(distinct x.branch) filter (where x.k = 'staff'), '[]'::jsonb)) end
    from (select 'staff' as k, s.id, s.branch_slug as branch, s.role, s.name, s.position as pos, s.test_as_guest
            from public.hub_staff_slots s where s.phone = p_phone
          union all
          select 'report', r.id, null, null, r.name, r.position, r.test_as_guest
            from public.hub_report_recipients r where r.phone = p_phone) x
   where p_phone is not null
$$;

-- a staff or report number that is not «يُعامَل كضيف للتجربة»: never a guest (no episode, no marketing, no review)
create function internal.hub_staff_excluded(p_phone text) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select not (j ->> 'test_as_guest')::boolean from (select internal.hub_staff_lookup(p_phone) as j) q where j is not null), false)
$$;

create function internal.hub_resume_minutes(p_branch text) returns integer
language sql stable security definer set search_path = '' as $$
  select coalesce((select t.resume_minutes from public.hub_team_branches t where t.branch_slug = p_branch), 15)
$$;

-- «مع الفريق» split in two (Ahmed, 15 Nov 2026): 'waiting' = handed to the team, no staff reply yet — the assistant keeps
-- answering what it can; 'resume' = a staff reply, then no staff message for the branch's «عودة المساعد» minutes — the
-- assistant resumes on the guest's message; null = silent (staff are on it; a cart order; a test-mode conversation; abuse)
create function internal.hub_human_phase(c public.hub_conversations, u public.hub_units, p_now timestamptz default now()) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when c.state <> 'human' then null
    when coalesce(c.human_reason, '') in ('test_mode', 'cart_order', 'abuse') then null
    when c.owner_kind is null then 'waiting'
    when c.owner_kind in ('staff', 'phone')
         and coalesce(c.staff_active_at, c.last_staff_at, c.state_changed_at) <= p_now - make_interval(mins => internal.hub_resume_minutes(u.branch_slug)) then 'resume'
    else null end
$$;

-- the branch's own number (its branch unit's channel)
create function internal.hub_branch_channel(p_branch text) returns uuid
language sql stable security definer set search_path = '' as $$
  select ch.id from public.hub_channels ch join public.hub_units u on u.id = ch.unit_id
   where u.kind = 'branch' and u.branch_slug = p_branch and not ch.is_test order by ch.created_at limit 1
$$;

create function internal.hub_mask_phone(p text) returns text
language sql immutable set search_path = '' as $$
  select case when p is null then null else '•••• ' || right(p, 3) end
$$;

-- the reasons a hand-off is not one: the assistant could not run, staff took it, a cart order, the test mode
create function internal.hub_alertable(p_reason text) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(p_reason, '') not in ('assistant_off', 'unit_off', 'budget_cap', 'budget_unset', 'api_credit', 'test_mode', 'take_over', 'phone_reply', 'cart_order')
$$;

-- ───────────────────────────────────────────── 5. the conversation's hand-off ─────────────────────────────────────────────
create function internal.hub_conv_team_before() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.owner_kind in ('staff', 'phone') and (old.owner_kind is distinct from new.owner_kind or new.last_staff_at is distinct from old.last_staff_at) then
    new.staff_active_at := now();
  end if;
  -- a new hand-off: into «مع الفريق», or handed again after the assistant resumed from a staff reply
  if new.state = 'human' and (old.state <> 'human' or (old.owner_kind in ('staff', 'phone') and new.owner_kind is null)) and internal.hub_alertable(new.human_reason) then
    new.handoff_id := gen_random_uuid();
  elsif new.state <> 'human' then
    new.handoff_id := null;
  end if;
  return new;
end;
$$;
create trigger hub_conversations_team_before before update on public.hub_conversations for each row execute function internal.hub_conv_team_before();

create function internal.hub_conv_team_after() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    update public.hub_handoffs set closed_at = coalesce(closed_at, now()) where id = old.handoff_id;
  end if;
  if new.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, is_test)
    select new.handoff_id, new.id, new.unit_id, u.branch_slug, new.human_reason, new.is_test from public.hub_units u where u.id = new.unit_id
    on conflict do nothing;
    perform internal.hub_handoff_queue(new.handoff_id, 'alert');
  elsif new.handoff_id is not null and new.last_staff_at is not null and new.last_staff_at is distinct from old.last_staff_at then
    update public.hub_handoffs set first_reply_at = coalesce(first_reply_at, new.last_staff_at) where id = new.handoff_id;
  end if;
  return null;
end;
$$;

-- the alert of a hand-off (kind alert): every active slot of the branch on shift now; nobody on shift → the managers; no
-- slot → email only (the existing waiting email). An escalation: the managers not yet alerted for this hand-off.
create function internal.hub_handoff_queue(p_handoff uuid, p_kind text, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff for update;
  if h.id is null or h.closed_at is not null then return 0; end if;
  v_channel := internal.hub_branch_channel(h.branch_slug);
  if p_kind = 'alert' then
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and internal.hub_slot_covers(s, p_now)
      on conflict do nothing;
      get diagnostics v_n = row_count;
      if v_n = 0 then
        insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
        select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
         where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
        on conflict do nothing;
        get diagnostics v_n = row_count;
      end if;
    end if;
    update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
  else
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'escalation', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
         and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
  end if;
  return v_n;
end;
$$;
create trigger hub_conversations_team_after after update on public.hub_conversations for each row execute function internal.hub_conv_team_after();

-- ───────────────────────────────────────────── 6. sending the alerts and reports (service role, wa-automation / hub-agent) ─────────────────────────────────────────────
create function internal.hub_kick_staff_sender() returns bigint
language plpgsql security definer set search_path = '' as $$
declare
  v_url text := internal.vault_value('job_sweep_url');
  v_token text := internal.vault_value('wa_cron_token');
begin
  if coalesce(v_url, '') = '' or coalesce(v_token, '') = '' or v_url !~ '/functions/v1/' then return null; end if;
  return net.http_post(
    url := regexp_replace(v_url, '/functions/v1/.*$', '/functions/v1/wa-automation'),
    body := jsonb_build_object('action', 'hub-staff'),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-armada-cron', v_token),
    timeout_milliseconds := 30000);
end;
$$;

-- the sends waiting, each with what its template needs — the guest's name and phone are read here, never stored
create function public.hub_staff_sends_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s record;
  v_out jsonb := '[]'::jsonb;
begin
  for s in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, coalesce(sl.phone, rr.phone) as to_phone,
                  coalesce(sl.active, rr.active, false) as target_active, h.token, h.branch_slug, h.summary, h.ref_text, h.reason, h.conversation_id,
                  h.closed_at, h.first_reply_at
             from public.hub_staff_sends x
             left join public.hub_channels ch on ch.id = x.channel_id
             left join public.hub_staff_slots sl on sl.id = x.slot_id
             left join public.hub_report_recipients rr on rr.id = x.recipient_id
             left join public.hub_handoffs h on h.id = x.handoff_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false) order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of x skip locked loop
    -- an alert or escalation whose hand-off was answered or closed meanwhile is not sent
    if s.to_phone is null or not s.target_active or s.from_address is null
       or (s.kind in ('alert', 'escalation') and (s.closed_at is not null or s.first_reply_at is not null)) then
      update public.hub_staff_sends set status = 'skipped', error_code = case when s.from_address is null then 'no_channel' when s.to_phone is null or not s.target_active then 'no_recipient' else 'answered' end, updated_at = now()
       where id = s.id;
      continue;
    end if;
    update public.hub_staff_sends set status = 'pending', updated_at = now() where id = s.id;
    v_out := v_out || jsonb_build_object(
      'id', s.id, 'kind', s.kind, 'template', s.template, 'language', 'ar', 'is_test', s.is_test,
      'channel_id', s.channel_id, 'from', s.from_address, 'waba_id', s.waba_id, 'sending_enabled', s.sending_enabled, 'to', s.to_phone,
      'handoff', case when s.handoff_id is not null then (
        select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'summary', s.summary, 'ref', s.ref_text, 'reason', s.reason,
                 'guest_name', coalesce((select nullif(btrim(r.guest_name), '') from public.reservations r where r.phone = g.phone and not r.is_test order by r.created_at desc limit 1),
                                        nullif(btrim(g.wa_profile_name), '')),
                 'guest_phone', g.phone)
          from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id where c.id = s.conversation_id) end,
      'report', case when s.kind = 'report' then (select jsonb_build_object('day', d.day, 'data', d.data) from public.hub_daily_reports d where d.day = s.report_day)
                     when s.kind = 'report_test' then jsonb_build_object('day', s.report_day, 'data', s.payload) end);
  end loop;
  return v_out;
end;
$$;

create function public.hub_staff_send_finish(p_send uuid, p_status text, p_provider_id text, p_error_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if p_status not in ('accepted', 'sent', 'delivered', 'read', 'failed', 'test', 'skipped') then raise exception 'hub_staff_send_finish' using errcode = '22023'; end if;
  update public.hub_staff_sends
     set status = p_status, provider_message_id = coalesce(nullif(left(p_provider_id, 200), ''), provider_message_id),
         error_code = case when p_status in ('failed', 'skipped') then coalesce(nullif(left(p_error_code, 40), ''), p_status) end, updated_at = now()
   where id = p_send and status = 'pending';
  return jsonb_build_object('ok', found);
end;
$$;

-- a template read from YCloud before its first use (one name, language and number): its status and body
create function public.hub_template_read_store(p_channel uuid, p_item jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.hub_channels c where c.id = p_channel) then raise exception 'not_found' using errcode = '22023'; end if;
  if coalesce(p_item ->> 'name', '') !~ '^[a-z0-9_]{1,512}$' or coalesce(p_item ->> 'language', '') !~ '^[a-z]{2,3}(_[A-Z]{2})?$'
     or char_length(coalesce(p_item ->> 'status', '')) not between 1 and 40 then raise exception 'hub_template_item' using errcode = '22023'; end if;
  insert into public.hub_templates as t (channel_id, name, language, category, status, reason, body, read_at)
  values (p_channel, p_item ->> 'name', p_item ->> 'language', nullif(left(coalesce(p_item ->> 'category', ''), 40), ''), upper(p_item ->> 'status'),
          nullif(left(coalesce(p_item ->> 'reason', ''), 300), ''), nullif(left(coalesce(p_item ->> 'body', ''), 2000), ''), now())
  on conflict (channel_id, name, language) do update
     set category = excluded.category, status = excluded.status, reason = excluded.reason, body = coalesce(excluded.body, t.body), read_at = excluded.read_at;
  return jsonb_build_object('ok', true);
end;
$$;

create function public.hub_template_get(p_channel uuid, p_name text, p_language text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_build_object('status', t.status, 'body', t.body, 'read_at', t.read_at) from public.hub_templates t
                    where t.channel_id = p_channel and t.name = p_name and t.language = p_language), '{}'::jsonb)
$$;

-- ───────────────────────────────────────────── 7. the daily report ─────────────────────────────────────────────
-- the figures of one Riyadh day (or of today until p_to): per branch, counts only — never money
create function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z)
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.published_at >= v_from and k.published_at < v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    'built_at', now());
end;
$$;

-- at the send time (Riyadh), once: the previous day's report — stored, one send per active recipient from the Airport Road
-- number, the email archive after it (wa-automation). Not after 6 hours past the time (a late cron never sends it at night).
create function internal.hub_report_tick(p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_local timestamp := p_now at time zone 'Asia/Riyadh';
  v_time time := coalesce((select c.send_time from public.hub_report_config c where c.id), '08:00');
  v_day date := (p_now at time zone 'Asia/Riyadh')::date - 1;
  v_n integer := 0;
  v_channel uuid := internal.hub_branch_channel('airport-road');
begin
  if v_local::time < v_time or v_local::time > v_time + interval '6 hours' and v_time < '18:00' then return 0; end if;
  if exists (select 1 from public.hub_daily_reports d where d.day = v_day) then return 0; end if;
  insert into public.hub_daily_reports (day, data) values (v_day, internal.hub_report_data(v_day)) on conflict do nothing;
  if not found then return 0; end if;
  if v_channel is not null then
    insert into public.hub_staff_sends (kind, report_day, recipient_id, channel_id, template)
    select 'report', v_day, r.id, v_channel, 'hub_daily_report' from public.hub_report_recipients r where r.active
    on conflict do nothing;
    get diagnostics v_n = row_count;
  end if;
  return v_n + 1;
end;
$$;

-- the email archive of a stored report (once): the hub_summary recipients (CLAUDE.md §8 «Delivery»: confirmed filters only)
create function public.hub_report_email_claim() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare d public.hub_daily_reports;
begin
  select * into d from public.hub_daily_reports x where x.emailed_at is null and x.built_at > now() - interval '1 day' order by x.day limit 1 for update skip locked;
  if d.day is null then return jsonb_build_object('report', null); end if;
  update public.hub_daily_reports set emailed_at = now() where day = d.day;
  return jsonb_build_object('report', jsonb_build_object('day', d.day, 'data', d.data),
    'recipients', (select coalesce(jsonb_agg(distinct r.email), '[]'::jsonb) from public.booking_notification_recipients r
                    where r.scope = 'hub_summary' and r.active and r.filter_confirmed_at is not null));
end;
$$;

-- every minute (pg_cron hub-team): the escalations, the daily report, the sender kicked when something waits; summaries
-- older than 30 days and the colleague chat older than 30 days removed
create function public.hub_team_cron(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  h record;
  v_esc integer := 0;
  v_rep integer;
  v_req bigint;
begin
  for h in select x.id from public.hub_handoffs x join public.hub_team_branches b on b.branch_slug = x.branch_slug
            where x.closed_at is null and x.escalated_at is null and x.opened_at is null and x.first_reply_at is null and x.alerted_at is not null
              and x.created_at <= p_now - make_interval(mins => b.escalate_minutes)
            order by x.created_at limit 50 for update of x skip locked loop
    v_esc := v_esc + internal.hub_handoff_queue(h.id, 'escalation', p_now);
  end loop;
  v_rep := internal.hub_report_tick(p_now);
  update public.hub_handoffs set summary = null where summary is not null and created_at < p_now - interval '30 days';
  delete from public.hub_staff_messages where created_at < p_now - interval '30 days';
  if exists (select 1 from public.hub_staff_sends s where s.status = 'queued' and not s.is_test)
     or exists (select 1 from public.hub_daily_reports d where d.emailed_at is null and d.built_at > p_now - interval '1 day') then
    v_req := internal.hub_kick_staff_sender();
  end if;
  return jsonb_build_object('ok', true, 'escalations', v_esc, 'report', v_rep, 'request', v_req);
end;
$$;

-- ───────────────────────────────────────────── 8. the colleague chat (service role, wa-automation) ─────────────────────────────────────────────
-- a message from a staff or report number to a branch number: stored (30 days), with what the reply may say — counts, who
-- is on shift, the links of the waiting conversations; never a guest's name, number or words
create function public.hub_staff_chat_begin(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_who jsonb := internal.hub_staff_lookup(p ->> 'phone');
  ch public.hub_channels;
  u public.hub_units;
  v_id uuid;
  v_branches text[];
  v_today jsonb;
  v_facts jsonb := '{}'::jsonb;
  b text;
  st jsonb;
begin
  if v_who is null then return jsonb_build_object('staff', false); end if;
  if (v_who ->> 'test_as_guest')::boolean then return jsonb_build_object('staff', false, 'test_as_guest', true); end if;
  select * into ch from public.hub_channels where address = p ->> 'channel' order by created_at limit 1;
  if ch.id is null then return jsonb_build_object('staff', true, 'ok', false, 'reason', 'no_channel'); end if;
  select * into u from public.hub_units where id = ch.unit_id;
  insert into public.hub_staff_messages (who_kind, who_id, channel_id, direction, body, provider_message_id, is_test)
  values (v_who ->> 'kind', (v_who ->> 'who_id')::uuid, ch.id, 'in', left(p ->> 'text', 4096), nullif(p ->> 'provider_id', ''), coalesce((p ->> 'is_test')::boolean, false))
  on conflict (provider_message_id) do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('staff', true, 'ok', false, 'reason', 'duplicate'); end if;
  v_branches := case when jsonb_array_length(v_who -> 'branches') > 0 then array(select jsonb_array_elements_text(v_who -> 'branches')) else array['airport-road', 'shafa-road'] end;
  v_today := internal.hub_report_data((now() at time zone 'Asia/Riyadh')::date, now());
  foreach b in array v_branches loop
    v_facts := v_facts || jsonb_build_object(b, jsonb_build_object(
      'waiting_for_staff', (select count(*) from public.hub_conversations c join public.hub_units x on x.id = c.unit_id
                              where x.branch_slug = b and c.state = 'human' and c.owner_kind is null and not c.is_test),
      'with_staff', (select count(*) from public.hub_conversations c join public.hub_units x on x.id = c.unit_id
                       where x.branch_slug = b and c.state = 'human' and c.owner_kind in ('staff', 'phone') and not c.is_test),
      'on_shift_now', (select coalesce(jsonb_agg(s.name order by s.position), '[]'::jsonb) from public.hub_staff_slots s
                         where s.branch_slug = b and s.active and internal.hub_slot_covers(s, now())),
      'today', jsonb_build_object('conversations', v_today #> array['branches', b, 'conversations'], 'handed_to_team', v_today #> array['branches', b, 'handed'],
                                  'answered_by_us', v_today #> array['branches', b, 'assistant'], 'chat_bookings', v_today #> array['branches', b, 'bookings']),
      'links', (select coalesce(jsonb_agg('https://admin.armadaresidence.com/?hub_c=' || z.token), '[]'::jsonb)
                  from (select h.token from public.hub_handoffs h join public.hub_conversations c on c.id = h.conversation_id
                         where h.branch_slug = b and h.closed_at is null and c.state = 'human' and c.owner_kind is null and not h.is_test
                         order by h.created_at limit 3) z)));
  end loop;
  st := internal.hub_budget_state();
  return jsonb_build_object('staff', true, 'ok', true, 'message_id', v_id, 'kind', v_who ->> 'kind', 'name', split_part(btrim(v_who ->> 'name'), ' ', 1),
    'role', v_who ->> 'role', 'unit', jsonb_build_object('id', u.id, 'key', u.key, 'branch', u.branch_slug),
    'gate', internal.hub_engine_ready() and internal.hub_setting_bool('hub_assistant_on') and ch.sending_enabled
            and not coalesce((st ->> 'capped')::boolean, false) and not coalesce((st ->> 'unset')::boolean, false)
            and not coalesce((st ->> 'api_credit')::boolean, false),
    'facts', v_facts,
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when x.direction = 'in' then 'colleague' else 'us' end, 'body', x.body) order by x.created_at), '[]'::jsonb)
                  from (select m.* from public.hub_staff_messages m where m.who_id = (v_who ->> 'who_id')::uuid and m.id <> v_id and m.body is not null
                          and m.created_at > now() - interval '24 hours' order by m.created_at desc limit 10) x),
    'models', (select s.value from public.settings s where s.key = 'hub_models'),
    'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'now', to_char(now() at time zone 'Asia/Riyadh', 'HH24:MI'));
end;
$$;

create function public.hub_staff_chat_finish(p_message uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  m public.hub_staff_messages;
  x jsonb;
  v_unit uuid;
  v_cost numeric := 0;
begin
  select * into m from public.hub_staff_messages where id = p_message and direction = 'in';
  if m.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select ch.unit_id into v_unit from public.hub_channels ch where ch.id = m.channel_id;
  for x in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if v_unit is not null and coalesce((x ->> 'input_tokens')::bigint, 0) + coalesce((x ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(v_unit, 'staff_chat', 'staff', x ->> 'model', (x ->> 'input_tokens')::bigint, (x ->> 'output_tokens')::bigint, m.is_test);
    end if;
  end loop;
  if nullif(btrim(coalesce(p ->> 'body', '')), '') is not null then
    insert into public.hub_staff_messages (who_kind, who_id, channel_id, direction, body, provider_message_id, status, error_code, is_test)
    values (m.who_kind, m.who_id, m.channel_id, 'out', left(p ->> 'body', 4096), nullif(left(coalesce(p ->> 'provider_id', ''), 200), ''),
            case when p ->> 'status' in ('accepted', 'sent', 'delivered', 'read', 'failed', 'skipped', 'test') then p ->> 'status' else 'failed' end,
            nullif(left(coalesce(p ->> 'error_code', ''), 40), ''), m.is_test)
    on conflict (provider_message_id) do nothing;
  end if;
  return jsonb_build_object('ok', true, 'cost_usd', v_cost);
end;
$$;

-- a number writing to a branch number: staff / report (not a guest), or null — the router asks before storing anything
create function public.hub_staff_number(p_phone text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select internal.hub_staff_lookup(p_phone)
$$;

-- ───────────────────────────────────────────── 9. the dashboard «الفريق والتقارير» ─────────────────────────────────────────────
create function public.hub_team_get() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_edit boolean := internal.can('hub_team', 'edit');
  v_admin boolean := internal.is_system_admin();
begin
  if not internal.can('hub_team', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'now', now(), 'can_edit', v_edit, 'is_system_admin', v_admin,
    'branches', (select coalesce(jsonb_agg(jsonb_build_object(
        'slug', b.slug, 'name', b.name_ar, 'can_edit', v_edit and internal.can_branch(b.slug),
        'resume_minutes', t.resume_minutes, 'escalate_minutes', t.escalate_minutes,
        'channel', (select ch.sending_enabled from public.hub_channels ch where ch.id = internal.hub_branch_channel(b.slug)),
        'slots', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'position', s.position, 'name', s.name,
                    'phone', case when v_edit and internal.can_branch(b.slug) then s.phone else internal.hub_mask_phone(s.phone) end,
                    'role', s.role, 'days', to_jsonb(s.days), 'start_time', to_char(s.start_time, 'HH24:MI'), 'end_time', to_char(s.end_time, 'HH24:MI'),
                    'active', s.active, 'test_as_guest', s.test_as_guest, 'consent_at', s.consent_at,
                    'on_shift', s.active and internal.hub_slot_covers(s, now())) order by s.position), '[]'::jsonb)
                    from public.hub_staff_slots s where s.branch_slug = b.slug)
      ) order by b.sort, b.slug), '[]'::jsonb)
      from public.branches b join public.hub_team_branches t on t.branch_slug = b.slug where internal.can_branch(b.slug)),
    'report', jsonb_build_object(
      'send_time', (select to_char(c.send_time, 'HH24:MI') from public.hub_report_config c where c.id),
      'recipients', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'position', r.position, 'name', r.name,
                       'phone', case when v_admin then r.phone else internal.hub_mask_phone(r.phone) end, 'staff_user_id', r.staff_user_id,
                       'staff_name', internal.staff_name(r.staff_user_id), 'active', r.active, 'test_as_guest', r.test_as_guest, 'consent_at', r.consent_at,
                       'mine', r.staff_user_id = auth.uid()) order by r.position), '[]'::jsonb) from public.hub_report_recipients r),
      'email_recipients', (select count(*) from public.booking_notification_recipients r where r.scope = 'hub_summary' and r.active and r.filter_confirmed_at is not null),
      'last', (select jsonb_build_object('day', d.day, 'built_at', d.built_at) from public.hub_daily_reports d order by d.day desc limit 1),
      'staff_users', case when v_admin then (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'name', s.full_name) order by s.full_name), '[]'::jsonb)
                                               from public.staff s where s.active) end));
end;
$$;

-- a slot added or changed (hub_team: edit on its branch): returns the row as it was, for «تراجع»
create function public.hub_staff_slot_save(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_branch text := p ->> 'branch';
  v_id uuid := case when coalesce(p ->> 'id', '') ~ '^[0-9a-f-]{36}$' then (p ->> 'id')::uuid end;
  o public.hub_staff_slots;
  v_name text := btrim(coalesce(p ->> 'name', ''));
  v_phone text := btrim(coalesce(p ->> 'phone', ''));
  v_days smallint[];
  v_pos smallint;
  v_batch uuid;
begin
  if not internal.can('hub_team', 'edit') or not internal.can_branch(v_branch) then raise exception 'forbidden' using errcode = '42501'; end if;
  if not exists (select 1 from public.hub_team_branches t where t.branch_slug = v_branch) then raise exception 'hub_slot_branch' using errcode = '22023'; end if;
  if char_length(v_name) not between 2 and 60 then raise exception 'hub_slot_name' using errcode = '22023'; end if;
  if v_phone !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'hub_slot_phone' using errcode = '22023'; end if;
  if coalesce(p ->> 'role', '') not in ('manager', 'staff') then raise exception 'hub_slot_role' using errcode = '22023'; end if;
  if jsonb_typeof(p -> 'days') <> 'array' or exists (select 1 from jsonb_array_elements(p -> 'days') d where d::text !~ '^[0-6]$') then
    raise exception 'hub_slot_days' using errcode = '22023';
  end if;
  v_days := array(select distinct (d #>> '{}')::smallint from jsonb_array_elements(p -> 'days') d order by 1);
  if coalesce(p ->> 'start_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(p ->> 'end_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     or p ->> 'start_time' = p ->> 'end_time' then raise exception 'hub_slot_hours' using errcode = '22023'; end if;
  if not coalesce((p ->> 'consent')::boolean, false) then raise exception 'hub_slot_consent' using errcode = '22023'; end if;
  if v_id is not null then select * into o from public.hub_staff_slots where id = v_id for update; end if;
  if o.id is not null and o.branch_slug <> v_branch then raise exception 'hub_slot_branch' using errcode = '22023'; end if;
  if exists (select 1 from public.hub_staff_slots s where s.branch_slug = v_branch and s.phone = v_phone and s.id is distinct from v_id) then
    raise exception 'hub_slot_phone_taken' using errcode = '22023';
  end if;
  v_batch := internal.begin_batch();
  if o.id is not null then
    update public.hub_staff_slots
       set name = v_name, phone = v_phone, role = p ->> 'role', days = v_days, start_time = (p ->> 'start_time')::time, end_time = (p ->> 'end_time')::time,
           active = coalesce((p ->> 'active')::boolean, true), test_as_guest = coalesce((p ->> 'test_as_guest')::boolean, false),
           consent_at = coalesce(consent_at, now()), consent_by = coalesce(consent_by, auth.uid())
     where id = o.id;
  else
    if (select count(*) from public.hub_staff_slots s where s.branch_slug = v_branch) >= 5 then raise exception 'hub_slots_full' using errcode = '22023'; end if;
    v_pos := case when coalesce(p ->> 'position', '') ~ '^[1-5]$' and not exists (select 1 from public.hub_staff_slots s where s.branch_slug = v_branch and s.position = (p ->> 'position')::smallint)
                  then (p ->> 'position')::smallint
                  else (select min(g)::smallint from generate_series(1, 5) g where not exists (select 1 from public.hub_staff_slots s where s.branch_slug = v_branch and s.position = g)) end;
    insert into public.hub_staff_slots (id, branch_slug, position, name, phone, role, days, start_time, end_time, active, test_as_guest, consent_at, consent_by)
    values (coalesce(v_id, gen_random_uuid()), v_branch, v_pos, v_name, v_phone, p ->> 'role', v_days, (p ->> 'start_time')::time, (p ->> 'end_time')::time,
            coalesce((p ->> 'active')::boolean, true), coalesce((p ->> 'test_as_guest')::boolean, false),
            coalesce(case when coalesce(p ->> 'consent_at', '') <> '' then (p ->> 'consent_at')::timestamptz end, now()), auth.uid())
    returning id into v_id;
  end if;
  return jsonb_build_object('ok', true, 'id', coalesce(o.id, v_id), 'batch_id', v_batch,
    'previous', case when o.id is not null then jsonb_build_object('id', o.id, 'branch', o.branch_slug, 'position', o.position, 'name', o.name, 'phone', o.phone, 'role', o.role,
                  'days', to_jsonb(o.days), 'start_time', to_char(o.start_time, 'HH24:MI'), 'end_time', to_char(o.end_time, 'HH24:MI'), 'active', o.active,
                  'test_as_guest', o.test_as_guest, 'consent', true, 'consent_at', o.consent_at) end);
end;
$$;

create function public.hub_staff_slot_delete(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.hub_staff_slots;
  v_batch uuid;
begin
  select * into o from public.hub_staff_slots where id = p_id for update;
  if o.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can('hub_team', 'edit') or not internal.can_branch(o.branch_slug) then raise exception 'forbidden' using errcode = '42501'; end if;
  v_batch := internal.begin_batch();
  delete from public.hub_staff_slots where id = o.id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch,
    'previous', jsonb_build_object('id', o.id, 'branch', o.branch_slug, 'position', o.position, 'name', o.name, 'phone', o.phone, 'role', o.role,
                  'days', to_jsonb(o.days), 'start_time', to_char(o.start_time, 'HH24:MI'), 'end_time', to_char(o.end_time, 'HH24:MI'), 'active', o.active,
                  'test_as_guest', o.test_as_guest, 'consent', true, 'consent_at', o.consent_at));
end;
$$;

create function public.hub_team_branch_save(p_branch text, p_resume integer, p_escalate integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.hub_team_branches;
  v_batch uuid;
begin
  if not internal.can('hub_team', 'edit') or not internal.can_branch(p_branch) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into o from public.hub_team_branches where branch_slug = p_branch for update;
  if o.branch_slug is null then raise exception 'not_found' using errcode = '22023'; end if;
  if p_resume is null or p_resume not between 5 and 240 then raise exception 'hub_team_resume' using errcode = '22023'; end if;
  if p_escalate is null or p_escalate not between 2 and 120 then raise exception 'hub_team_escalate' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_team_branches set resume_minutes = p_resume, escalate_minutes = p_escalate, updated_at = now(), updated_by = auth.uid() where branch_slug = p_branch;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'previous', jsonb_build_object('resume_minutes', o.resume_minutes, 'escalate_minutes', o.escalate_minutes));
end;
$$;

create function public.hub_report_recipient_save(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid := case when coalesce(p ->> 'id', '') ~ '^[0-9a-f-]{36}$' then (p ->> 'id')::uuid end;
  o public.hub_report_recipients;
  v_name text := btrim(coalesce(p ->> 'name', ''));
  v_phone text := btrim(coalesce(p ->> 'phone', ''));
  v_user uuid := case when coalesce(p ->> 'staff_user_id', '') ~ '^[0-9a-f-]{36}$' then (p ->> 'staff_user_id')::uuid end;
  v_pos smallint;
  v_batch uuid;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(v_name) not between 2 and 60 then raise exception 'hub_slot_name' using errcode = '22023'; end if;
  if v_phone !~ '^\+[1-9][0-9]{7,14}$' then raise exception 'hub_slot_phone' using errcode = '22023'; end if;
  if not coalesce((p ->> 'consent')::boolean, false) then raise exception 'hub_slot_consent' using errcode = '22023'; end if;
  if v_user is not null and not exists (select 1 from public.staff s where s.user_id = v_user and s.active) then raise exception 'hub_report_user' using errcode = '22023'; end if;
  if v_id is not null then select * into o from public.hub_report_recipients where id = v_id for update; end if;
  if exists (select 1 from public.hub_report_recipients r where r.phone = v_phone and r.id is distinct from v_id) then raise exception 'hub_slot_phone_taken' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  if o.id is not null then
    update public.hub_report_recipients
       set name = v_name, phone = v_phone, staff_user_id = v_user, active = coalesce((p ->> 'active')::boolean, true),
           test_as_guest = coalesce((p ->> 'test_as_guest')::boolean, false), consent_at = coalesce(consent_at, now()), consent_by = coalesce(consent_by, auth.uid())
     where id = o.id;
  else
    if (select count(*) from public.hub_report_recipients) >= 3 then raise exception 'hub_report_full' using errcode = '22023'; end if;
    v_pos := case when coalesce(p ->> 'position', '') ~ '^[1-3]$' and not exists (select 1 from public.hub_report_recipients r where r.position = (p ->> 'position')::smallint)
                  then (p ->> 'position')::smallint
                  else (select min(g)::smallint from generate_series(1, 3) g where not exists (select 1 from public.hub_report_recipients r where r.position = g)) end;
    insert into public.hub_report_recipients (id, position, name, phone, staff_user_id, active, test_as_guest, consent_at, consent_by)
    values (coalesce(v_id, gen_random_uuid()), v_pos, v_name, v_phone, v_user, coalesce((p ->> 'active')::boolean, true), coalesce((p ->> 'test_as_guest')::boolean, false),
            coalesce(case when coalesce(p ->> 'consent_at', '') <> '' then (p ->> 'consent_at')::timestamptz end, now()), auth.uid())
    returning id into v_id;
  end if;
  return jsonb_build_object('ok', true, 'id', coalesce(o.id, v_id), 'batch_id', v_batch,
    'previous', case when o.id is not null then jsonb_build_object('id', o.id, 'position', o.position, 'name', o.name, 'phone', o.phone, 'staff_user_id', o.staff_user_id,
                  'active', o.active, 'test_as_guest', o.test_as_guest, 'consent', true, 'consent_at', o.consent_at) end);
end;
$$;

