create function public.hub_report_config_save(p_send_time text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_old time;
  v_batch uuid;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(p_send_time, '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'hub_report_time' using errcode = '22023'; end if;
  select c.send_time into v_old from public.hub_report_config c where c.id for update;
  v_batch := internal.begin_batch();
  update public.hub_report_config set send_time = p_send_time::time, updated_at = now(), updated_by = auth.uid() where id;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'previous', to_char(v_old, 'HH24:MI'));
end;
$$;

-- «إرسال تجربة لي»: today's report so far, to the signed-in user's number when it is in the list, else to the first recipient
create function public.hub_report_test() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_report_recipients;
  v_mine boolean := true;
  v_channel uuid := internal.hub_branch_channel('airport-road');
  v_day date := (now() at time zone 'Asia/Riyadh')::date;
begin
  if not internal.is_system_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into r from public.hub_report_recipients x where x.staff_user_id = auth.uid() order by x.position limit 1;
  if r.id is null then
    v_mine := false;
    select * into r from public.hub_report_recipients x order by x.position limit 1;
  end if;
  if r.id is null then raise exception 'hub_report_no_recipient' using errcode = '22023'; end if;
  if v_channel is null then raise exception 'hub_report_no_channel' using errcode = '22023'; end if;
  if exists (select 1 from public.hub_staff_sends s where s.kind = 'report_test' and s.created_at > now() - interval '1 minute') then
    raise exception 'hub_report_test_wait' using errcode = '22023';
  end if;
  insert into public.hub_staff_sends (kind, report_day, recipient_id, channel_id, template, payload)
  values ('report_test', v_day, r.id, v_channel, 'hub_daily_report', internal.hub_report_data(v_day, now()));
  perform internal.hub_kick_staff_sender();
  return jsonb_build_object('ok', true, 'recipient', r.name, 'mine', v_mine);
end;
$$;

-- a day's report as it was sent (or the figures of a day not sent yet), with its breakdown; ?hub_r= opens it
create function public.hub_report_get(p_day date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare d public.hub_daily_reports;
begin
  if not internal.can('hub_team', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_day is null or p_day > (now() at time zone 'Asia/Riyadh')::date or p_day < '2026-11-01' then raise exception 'hub_report_day' using errcode = '22023'; end if;
  select * into d from public.hub_daily_reports x where x.day = p_day;
  return jsonb_build_object('day', p_day, 'stored', d.day is not null, 'built_at', d.built_at,
    'data', coalesce(d.data, internal.hub_report_data(p_day, case when p_day = (now() at time zone 'Asia/Riyadh')::date then now() end)),
    'sends', (select jsonb_build_object('sent', count(*) filter (where s.status in ('accepted', 'sent', 'delivered', 'read')),
                                        'delivered', count(*) filter (where s.status in ('delivered', 'read')), 'read', count(*) filter (where s.status = 'read'),
                                        'failed', count(*) filter (where s.status in ('failed', 'skipped')))
                from public.hub_staff_sends s where s.kind = 'report' and s.report_day = p_day));
end;
$$;

-- ?hub_c=<token>: the conversation of a staff alert, when the signed-in user may see it; the first opening is recorded
create function public.hub_alert_open(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare h public.hub_handoffs;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{32}$' then return jsonb_build_object('allowed', false, 'reason', 'invalid'); end if;
  select * into h from public.hub_handoffs where token = p_token;
  if h.id is null then return jsonb_build_object('allowed', false, 'reason', 'not_found'); end if;
  if not internal.can_unit(h.unit_id, 'view') then return jsonb_build_object('allowed', false, 'reason', 'forbidden'); end if;
  if h.opened_at is null then
    update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'link' where id = h.id;
  end if;
  return jsonb_build_object('allowed', true, 'conversation_id', h.conversation_id);
end;
$$;

-- a thread opened in «المحادثات»: its waiting hand-off counts as opened (the escalation waits for neither)
create function public.hub_handoff_seen(p_conversation uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.hub_conversations;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or c.handoff_id is null or not internal.can_unit(c.unit_id, 'view') then return; end if;
  update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'inbox' where id = c.handoff_id and opened_at is null;
end;
$$;

-- ───────────────────────────────────────────── 10. the functions this session changes (copies of the latest definitions) ─────────────────────────────────────────────
-- hub_turn_queue (20261114200000, copied): the two halves of «مع الفريق» (H6c)

create or replace function public.hub_turn_queue(p_conversation uuid, p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  g public.guest_profiles;
  st jsonb;
  v_turn uuid;
  v_due timestamptz;
  v_kind text;
  v_burst integer := internal.hub_setting_int('hub_burst_ms', 4000);
  v_test_mode boolean;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or c.state = 'closed' then return jsonb_build_object('queued', false, 'reason', 'closed'); end if;
  if not exists (select 1 from public.hub_messages m where m.id = p_message and m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest') then
    return jsonb_build_object('queued', false, 'reason', 'not_guest');
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then return jsonb_build_object('queued', false, 'reason', 'blocked'); end if;
  st := internal.hub_assistant_state(u);
  if not (st ->> 'active')::boolean then
    perform internal.hub_to_team(c, case when st ->> 'reason' = 'unit_off' then 'assistant_off' else st ->> 'reason' end);
    return jsonb_build_object('queued', false, 'reason', st ->> 'reason');
  end if;
  v_test_mode := st ->> 'mode' = 'test';
  -- the try while the API credit is exhausted (at most every 30 minutes): reserved here
  if (st ->> 'credit_try')::boolean then
    update public.hub_alerts set payload = payload || jsonb_build_object('last_try_at', now()) where kind = 'api_credit' and acknowledged_at is null and not is_test;
  end if;
  if v_test_mode then
    -- a conversation that existed before «تجربة»: its run starts now
    if c.test_state is null then
      update public.hub_conversations set test_state = 'new' where id = c.id;
      c.test_state := 'new';
    end if;
    -- H6c: «بانتظار موظف» (a hand-off with no staff reply yet) is answered by the assistant in a test run as well
    v_kind := case when c.test_state = 'closed' then 'tag' else 'reply' end;
  else
    -- H6c: «بانتظار موظف» → the assistant keeps answering what it can; «مع موظف» → silent (tagging) until the branch's
    -- «عودة المساعد» minutes of staff silence, then the guest's message resumes it
    v_kind := case when c.state = 'human' and internal.hub_human_phase(c, u) is null then 'tag' else 'reply' end;
  end if;
  -- a pending turn of this conversation takes the message (the burst)
  update public.hub_turns set inbound_message_ids = case when p_message = any (inbound_message_ids) then inbound_message_ids else inbound_message_ids || p_message end
   where conversation_id = c.id and status = 'pending'
  returning id, due_at into v_turn, v_due;
  if v_turn is not null then return jsonb_build_object('queued', true, 'joined', true, 'turn_id', v_turn, 'due_at', v_due); end if;
  insert into public.hub_turns (conversation_id, unit_id, inbound_message_ids, first_inbound_id, kind, due_at, is_test)
  values (c.id, c.unit_id, array[p_message], p_message, v_kind, now() + make_interval(secs => v_burst / 1000.0), c.is_test)
  on conflict do nothing
  returning id, due_at into v_turn, v_due;
  if v_turn is null then
    select t.id, t.due_at into v_turn, v_due from public.hub_turns t where t.first_inbound_id = p_message;
    return jsonb_build_object('queued', false, 'reason', 'duplicate', 'turn_id', v_turn);
  end if;
  return jsonb_build_object('queued', true, 'turn_id', v_turn, 'due_at', v_due, 'kind', v_kind);
end;
$$;

-- hub_turn_claim (20261115100000, copied): the hand-off phase, the staff messages named in the history (H6c)

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    'replies_hour', (select count(*) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', h.body) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and m.body is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and r.is_test = c.is_test order by r.created_at desc limit 5) r),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'show_prices'), false)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

-- hub_turn_finish (20261114200000, copied): «بانتظار موظف» stays with the team; a resumed hand-off is a new one; the alert line (H6c)

create or replace function public.hub_turn_finish(p_turn uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  m jsonb;
  v_cost numeric := 0;
  v_one numeric;
  v_to text := nullif(p ->> 'state', '');
  v_from text;
  v_test boolean;
  v_status text;
  v_out jsonb := '[]'::jsonb;
  v_id uuid;
  v_topics text[] := array(select jsonb_array_elements_text(coalesce(p -> 'topics', '[]'::jsonb)));
  v_draft jsonb := p -> 'draft';
  v_send boolean := false;
  v_seq integer := 0;
  v_unit uuid;
  v_ready boolean;
begin
  select * into t from public.hub_turns where id = p_turn for update;
  if t.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if t.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running', 'status', t.status); end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  v_test := t.mode = 'test';
  -- the models: every call counts in the budget (test runs included)
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if m ->> 'layer' in ('understand', 'tag', 'compose', 'summary') and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_one := internal.hub_usage_add(t.unit_id, m ->> 'layer', 'turn', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, t.is_test);
      v_cost := v_cost + v_one;
    end if;
  end loop;
  update public.hub_turns
     set status = case when p ->> 'status' in ('done', 'failed', 'skipped') then p ->> 'status' else 'done' end,
         error = nullif(left(p ->> 'error', 40), ''), understanding = p -> 'understanding', decision = p -> 'decision',
         models = coalesce(p -> 'models', '[]'::jsonb), cost_usd = v_cost, guard_refusals = coalesce(p -> 'guard_refusals', '[]'::jsonb), finished_at = now()
   where id = t.id;
  -- topics and language: real data, whatever the mode
  update public.hub_conversations
     set topics = (select coalesce(array_agg(distinct x), '{}') from (select unnest(topics) x union select unnest(v_topics)) q where x ~ '^[a-z0-9_]{2,60}$'),
         language = coalesce(case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end, language),
         failed_understandings = case p ->> 'failed' when 'reset' then 0 when 'inc' then failed_understandings + 1 else failed_understandings end,
         out_of_scope = out_of_scope + case when coalesce((p ->> 'out_of_scope_inc')::boolean, false) then 1 else 0 end,
         tags = case when jsonb_typeof(p -> 'tags_add') = 'array'
                     then (select coalesce(array_agg(distinct x), '{}') from (select unnest(tags) x union select jsonb_array_elements_text(p -> 'tags_add')) q)
                     else tags end
   where id = c.id;
  if t.kind = 'tag' or p ->> 'status' in ('failed', 'skipped') and v_to is null then
    return jsonb_build_object('ok', true, 'messages', '[]'::jsonb, 'cost_usd', v_cost);
  end if;
  -- the draft (one open per conversation and run): a draft of another kind is superseded first
  if coalesce((p ->> 'draft_replace')::boolean, false) then
    update public.hub_drafts set status = 'superseded' where conversation_id = c.id and status = 'open' and sim = v_test;
  end if;
  if jsonb_typeof(v_draft) = 'object' then
    update public.hub_drafts set fields = coalesce(v_draft -> 'fields', fields), quote = coalesce(v_draft -> 'quote', quote), version = version + 1
     where conversation_id = c.id and status = 'open' and sim = v_test;
    if not found then
      insert into public.hub_drafts (conversation_id, kind, sim, fields, quote, is_test)
      values (c.id, coalesce(v_draft ->> 'kind', 'stay'), v_test, coalesce(v_draft -> 'fields', '{}'::jsonb), v_draft -> 'quote', c.is_test);
    end if;
  end if;
  if nullif(p ->> 'draft_close', '') is not null then
    update public.hub_drafts set status = p ->> 'draft_close' where conversation_id = c.id and status = 'open' and sim = v_test and p ->> 'draft_close' in ('abandoned', 'failed', 'superseded');
  end if;
  -- the next state: in «تجربة» the run's own state (test_state); otherwise the conversation's
  if v_test then
    v_from := coalesce(c.test_state, 'new');
    if v_to is not null and v_to <> v_from then
      update public.hub_conversations set test_state = v_to where id = c.id;
      insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
      values (c.id, 'test', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
    end if;
  else
    v_from := c.state;
    if v_to = 'human' and v_from = 'human' then
      if coalesce((p ->> 'resumed')::boolean, false) then
        -- resumed after a staff reply and handed again (H6c): a new hand-off, with its own staff alert
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', 'human', 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end, waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif p ->> 'resume_state' in ('inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then
        -- «بانتظار موظف»: where the assistant's flow stands while it waits (for the resume and «إعادة للمساعد»)
        update public.hub_conversations set state_before_human = p ->> 'resume_state' where id = c.id and state_before_human is distinct from p ->> 'resume_state';
      end if;
      if p ->> 'priority' = 'high' then
        update public.hub_conversations set priority = 'high' where id = c.id and priority <> 'high';
      end if;
    elsif v_to is not null and v_to <> v_from then
      if v_to = 'human' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', v_from, 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_before_human = case when v_from in ('new', 'inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then v_from else state_before_human end,
               state = 'human', state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end,
               waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif v_to = 'closed' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'close', v_from, 'closed', coalesce(nullif(p ->> 'reason', ''), 'assistant'), c.is_test);
        update public.hub_conversations set state = 'closed', state_changed_at = now(), closed_at = now(), waiting_since = null where id = c.id;
      else
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'state', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
        update public.hub_conversations set state = v_to, state_changed_at = now(), owner_kind = 'assistant', owner_staff_id = null where id = c.id;
      end if;
    elsif p ->> 'priority' = 'high' then
      update public.hub_conversations set priority = 'high' where id = c.id;
    end if;
  end if;
  -- the staff alert's line and the booking ref or room (H6c), on the conversation's waiting hand-off
  if not v_test and (nullif(p ->> 'handoff_summary', '') is not null or nullif(p ->> 'handoff_ref', '') is not null or coalesce((p ->> 'handoff_add')::boolean, false)) then
    update public.hub_handoffs h
       set summary = coalesce(h.summary, nullif(left(btrim(p ->> 'handoff_summary'), 120), '')),
           ref_text = coalesce(h.ref_text, nullif(left(btrim(p ->> 'handoff_ref'), 40), '')),
           additions = h.additions + case when coalesce((p ->> 'handoff_add')::boolean, false) then 1 else 0 end
      from public.hub_conversations x
     where x.id = c.id and h.id = x.handoff_id;
  end if;
  -- the hand-off note (code-composed, spec §2.6): an internal note at the top of the thread, never sent
  if nullif(btrim(coalesce(p ->> 'note', '')), '') is not null then
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, sent_at, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'system', 'note', left(btrim(p ->> 'note'), 2000), jsonb_build_object('handoff_note', true, 'test', v_test),
            'turn:' || t.id || ':note', case when v_test then 'test' else 'internal' end, now(), t.id, c.is_test)
    on conflict (idempotency_key) do nothing;
  end if;
  -- the messages: «تجربة» stored as test; «بموافقة الفريق» drafts wait for one tap, the notices go; live sends now
  select (ch.sending_enabled and internal.hub_setting_bool('hub_inbox_on') and g.hub_blocked_at is null and c.window_expires_at > now()) into v_ready
    from public.hub_channels ch, public.guest_profiles g where ch.id = c.channel_id and g.id = c.guest_profile_id;
  for m in select * from jsonb_array_elements(coalesce(p -> 'messages', '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    v_status := case when v_test then 'test'
                     -- «بموافقة الفريق»: every reply waits for one tap; «يرد تلقائيًا»: only a licensed topic goes by itself;
                     -- the hand-off notices go out in both (approved copy, spec §2.10)
                     when t.mode in ('shadow', 'live') and not coalesce((m ->> 'notice')::boolean, false)
                          and (t.mode = 'shadow' or not coalesce((m ->> 'licensed')::boolean, false)) then 'pending_approval'
                     when not coalesce(v_ready, false) then 'failed'
                     else 'queued' end;
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, language, idempotency_key, status, error_code, sent_at,
                                     source_card_ids, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'assistant', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end,
            left(m ->> 'body', 4096), coalesce(m -> 'payload', '{}'::jsonb) || jsonb_build_object('notice', coalesce((m ->> 'notice')::boolean, false), 'topics', to_jsonb(v_topics)),
            case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end,
            'turn:' || t.id || ':' || coalesce(m ->> 'seq', v_seq::text), v_status,
            case when v_status = 'failed' then 'not_ready' end, now() + make_interval(secs => v_seq * 0.001),
            coalesce(array(select x::uuid from jsonb_array_elements_text(coalesce(m -> 'source_card_ids', '[]'::jsonb)) x where x ~ '^[0-9a-f-]{36}$'), '{}'),
            t.id, c.is_test)
    on conflict (idempotency_key) do nothing
    returning id into v_id;
    if v_id is not null then
      if v_status = 'queued' then
        v_send := true;
        v_out := v_out || jsonb_build_object('id', v_id, 'kind', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end, 'body', left(m ->> 'body', 4096),
                                             'payload', coalesce(m -> 'payload', '{}'::jsonb), 'notice', coalesce((m ->> 'notice')::boolean, false));
      end if;
      if v_status = 'pending_approval' then
        update public.hub_licences set drafts = drafts + 1 where unit_id = t.unit_id and topic_key = any (v_topics);
      end if;
    end if;
  end loop;
  if v_seq > 0 and not v_test then update public.hub_conversations set last_assistant_at = now() where id = c.id; end if;
  -- «لم أعرف الإجابة» (not from a test run: nothing reaches a team)
  if not v_test and jsonb_typeof(p -> 'unanswered') = 'array' then
    perform internal.hub_unanswered_add(c, x::uuid, null, v_topics[1]) from jsonb_array_elements_text(p -> 'unanswered') x where x ~ '^[0-9a-f-]{36}$';
  end if;
  select unit_id into v_unit from public.hub_conversations where id = c.id;
  return jsonb_build_object('ok', true, 'cost_usd', v_cost, 'messages', v_out, 'send', v_send, 'test', v_test,
                            'alerts', exists (select 1 from public.hub_staff_sends s where s.status = 'queued' and not s.is_test),
                            'context', case when v_send then (select internal.hub_send_context(x) from public.hub_conversations x where x.id = c.id) end);
end;
$$;

-- hub_send_finish (20261114600000, copied): an assistant answer while «بانتظار موظف» never clears the wait (H6c)

create or replace function public.hub_send_finish(p_message uuid, p_status text, p_ycloud_id text, p_error_code text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_conv uuid;
  v_author text;
  v_notice boolean;
  v_ok boolean := p_status in ('accepted', 'sent', 'delivered', 'read', 'test');
begin
  if p_status is null or not (v_ok or p_status = 'failed') then raise exception 'hub_send_finish' using errcode = '22023'; end if;
  update public.hub_messages
     set status = p_status, provider_message_id = coalesce(nullif(left(p_ycloud_id, 200), ''), provider_message_id),
         error_code = case when p_status = 'failed' then coalesce(nullif(left(p_error_code, 40), ''), 'failed') end, sent_at = now()
   where id = p_message and status = 'queued' and direction = 'out'
  returning conversation_id, author, coalesce((payload ->> 'notice')::boolean, false) or coalesce((payload ->> 'handoff')::boolean, false) into v_conv, v_author, v_notice;
  if v_conv is null then return jsonb_build_object('ok', false, 'reason', 'not_queued'); end if;
  if v_ok and v_author = 'assistant' then
    update public.hub_conversations
       set last_assistant_at = now(),
           first_response_at = case when not v_notice and state <> 'human' then coalesce(first_response_at, case when waiting_since is not null then now() end) else first_response_at end,
           -- H6c: an answer while «بانتظار موظف» keeps the conversation waiting for the team
           waiting_since = case when v_notice or state = 'human' then waiting_since else null end
     where id = v_conv;
  elsif v_ok then
    update public.hub_conversations
       set last_staff_at = now(), first_response_at = coalesce(first_response_at, case when waiting_since is not null then now() end), waiting_since = null
     where id = v_conv;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- wa_claim (20261113200000, copied): a staff or report number never gets a guest message (H6c)

create or replace function public.wa_claim(p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_out jsonb := '[]'::jsonb;
  w record;
  e record;
  v_lim integer := least(greatest(coalesce(p_limit, 20), 1), 100);
  v_code text;
begin
  -- the booking templates first (the time of day matters)
  for w in select m.*, r.status as r_status, r.guest_name, r.phone, r.profile_id
             from public.whatsapp_messages m join public.reservations r on r.id = m.reservation_id
            where m.status = 'queued' and m.template in ('arrival_reminder', 'stay_review')
            order by m.created_at limit v_lim for update of m skip locked loop
    -- H6c: a staff or report number is never a guest (no review, no reminder)
    if internal.hub_staff_excluded(w.phone) then
      update public.whatsapp_messages set status = 'skipped', error_code = 'staff_number', updated_at = now() where id = w.id;
      continue;
    end if;
    if w.r_status <> 'confirmed'
       or (w.template = 'stay_review' and exists (select 1 from public.guest_profiles g where g.id = w.profile_id and internal.wa_opted_out(g))) then
      update public.whatsapp_messages set status = 'skipped', error_code = case when w.r_status <> 'confirmed' then 'not_confirmed' else 'opted_out' end, updated_at = now() where id = w.id;
      continue;
    end if;
    update public.whatsapp_messages set status = 'pending', updated_at = now() where id = w.id;
    v_out := v_out || jsonb_build_object('table', 'whatsapp_messages', 'id', w.id, 'template', w.template, 'language', w.language, 'branch', w.branch,
                                         'ref', w.ref, 'name', w.guest_name, 'phone', w.phone, 'is_test', w.is_test);
  end loop;
  v_lim := v_lim - jsonb_array_length(v_out);
  if v_lim <= 0 then return v_out; end if;
  for e in select m.*, g.phone, g.name, internal.eyab_offer_ok(g) as ok, g.marketing_hold_at as held, c.state as c_state, c.vars as c_vars
             from public.eyab_messages m
             left join public.guest_profiles g on g.id = m.profile_id
             left join public.eyab_campaigns c on c.id = m.campaign_id
            where m.status = 'queued' and m.trigger in ('auto', 'campaign')
            order by m.created_at limit v_lim for update of m skip locked loop
    v_code := case when internal.hub_staff_excluded(e.phone) then 'staff_number' end;
    if v_code is not null then
      null;
    elsif e.template = 'optout_reply' then
      if e.profile_id is null or e.phone is null then v_code := 'not_eligible'; end if;
    elsif e.profile_id is null or not coalesce(e.ok, false) then
      v_code := 'not_eligible';
    elsif e.trigger = 'campaign' and e.c_state is distinct from 'sending' then
      v_code := 'stopped';
    elsif e.template = 'eyab_welcome' and not internal.branch_switch('wa_eyab_welcome', e.branch) then
      v_code := 'switch_off';
    elsif e.template = 'eyab_offer' and e.held is not null then
      v_code := 'held';
    end if;
    if v_code is not null then
      update public.eyab_messages set status = 'skipped', error_code = v_code, updated_at = now() where id = e.id;
      continue;
    end if;
    update public.eyab_messages set status = 'pending', updated_at = now() where id = e.id;
    v_out := v_out || jsonb_build_object('table', 'eyab_messages', 'id', e.id, 'template', e.template, 'language', e.language, 'branch', e.branch,
                                         'campaign_id', e.campaign_id, 'name', e.name, 'phone', e.phone, 'is_test', e.is_test,
                                         'vars', case when e.c_vars is not null then e.c_vars -> e.language end);
  end loop;
  return v_out;
end;
$$;

-- wa_status_update (20261113200000, copied): + the staff alerts and reports (H6c)

create or replace function public.wa_status_update(p_ycloud_id text, p_status text, p_price numeric, p_currency text, p_error_code text) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_n integer := 0;
  v_m integer;
  v_rank jsonb := '{"queued": 0, "pending": 1, "accepted": 2, "sent": 3, "delivered": 4, "read": 5}';
begin
  if coalesce(p_ycloud_id, '') = '' or p_status not in ('accepted', 'sent', 'delivered', 'read', 'failed') then return 0; end if;
  update public.whatsapp_messages w
     set status = case when p_status = 'failed' then case when w.status in ('delivered', 'read') then w.status else 'failed' end
                       when coalesce((v_rank ->> w.status)::int, -1) < (v_rank ->> p_status)::int then p_status else w.status end,
         error_code = case when p_status = 'failed' and w.status not in ('delivered', 'read') then coalesce(p_error_code, w.error_code) else w.error_code end,
         price = coalesce(p_price, w.price), currency = coalesce(p_currency, w.currency), updated_at = now()
   where w.ycloud_id = p_ycloud_id and w.status not in ('test', 'skipped');
  get diagnostics v_m = row_count;
  v_n := v_n + v_m;
  update public.eyab_messages w
     set status = case when p_status = 'failed' then case when w.status in ('delivered', 'read') then w.status else 'failed' end
                       when coalesce((v_rank ->> w.status)::int, -1) < (v_rank ->> p_status)::int then p_status else w.status end,
         error_code = case when p_status = 'failed' and w.status not in ('delivered', 'read') then coalesce(p_error_code, w.error_code) else w.error_code end,
         price = coalesce(p_price, w.price), currency = coalesce(p_currency, w.currency), updated_at = now()
   where w.ycloud_id = p_ycloud_id and w.status not in ('test', 'skipped');
  get diagnostics v_m = row_count;
  v_n := v_n + v_m;
  -- the hub's outbound messages (an echo, later the inbox and the assistant); an inbound row never moves
  update public.hub_messages w
     set status = case when p_status = 'failed' then case when w.status in ('delivered', 'read') then w.status else 'failed' end
                       when coalesce((v_rank ->> w.status)::int, -1) < (v_rank ->> p_status)::int then p_status else w.status end,
         error_code = case when p_status = 'failed' and w.status not in ('delivered', 'read') then coalesce(left(p_error_code, 40), w.error_code) else w.error_code end,
         price = coalesce(p_price, w.price), currency = coalesce(p_currency, w.currency)
   where w.provider_message_id = p_ycloud_id and w.direction = 'out'
     and w.status in ('queued', 'accepted', 'sent', 'delivered', 'read', 'failed', 'approved');
  get diagnostics v_m = row_count;
  v_n := v_n + v_m;
  -- H6c: the staff alerts and the daily reports
  update public.hub_staff_sends w
     set status = case when p_status = 'failed' then case when w.status in ('delivered', 'read') then w.status else 'failed' end
                       when coalesce((v_rank ->> w.status)::int, -1) < (v_rank ->> p_status)::int then p_status else w.status end,
         error_code = case when p_status = 'failed' and w.status not in ('delivered', 'read') then coalesce(left(p_error_code, 40), w.error_code) else w.error_code end,
         price = coalesce(p_price, w.price), currency = coalesce(p_currency, w.currency), updated_at = now()
   where w.provider_message_id = p_ycloud_id and w.status not in ('test', 'skipped', 'queued');
  get diagnostics v_m = row_count;
  return v_n + v_m;
end;
$$;

-- hub_templates_store (20261113100000, copied): + the body YCloud stores (H6c)

create or replace function public.hub_templates_store(p_channel uuid, p_user uuid, p_items jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_batch uuid;
  r jsonb;
  v_n integer := 0;
  v_keep text[] := '{}';
begin
  if not exists (select 1 from public.hub_channels c where c.id = p_channel) then raise exception 'not_found' using errcode = '22023'; end if;
  if coalesce(jsonb_typeof(p_items), '') <> 'array' or jsonb_array_length(p_items) > 500 then raise exception 'hub_templates: a list' using errcode = '22023'; end if;
  perform internal.hub_act_as(p_user);
  v_batch := internal.begin_batch();
  for r in select * from jsonb_array_elements(p_items) loop
    continue when coalesce(r ->> 'name', '') !~ '^[a-z0-9_]+$' or char_length(r ->> 'name') > 512 or coalesce(r ->> 'language', '') !~ '^[a-z]{2,3}(_[A-Z]{2})?$'
               or char_length(coalesce(r ->> 'status', '')) not between 1 and 40;
    insert into public.hub_templates as t (channel_id, name, language, category, status, reason, read_at, body)
    values (p_channel, r ->> 'name', r ->> 'language', nullif(left(coalesce(r ->> 'category', ''), 40), ''), upper(r ->> 'status'),
            nullif(left(coalesce(r ->> 'reason', ''), 300), ''), now(), nullif(left(coalesce(r ->> 'body', ''), 2000), ''))
    on conflict (channel_id, name, language) do update
       set category = excluded.category, status = excluded.status, reason = excluded.reason, read_at = excluded.read_at, body = coalesce(excluded.body, t.body);
    v_keep := v_keep || ((r ->> 'name') || '|' || (r ->> 'language'));
    v_n := v_n + 1;
  end loop;
  delete from public.hub_templates where channel_id = p_channel and (name || '|' || language) <> all(v_keep);
  perform set_config('request.jwt.claims', '', true);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'count', v_n);
end;
$$;

-- ───────────────────────────────────────────── 10b. the team bank in the test lab ─────────────────────────────────────────────
-- The guest conversations of tests/hub-bank/conversations-team.jsonl (tags conversation + h6c): «بانتظار موظف» answers,
-- a second thing joined to the same hand-off, a staff reply then silence, the resume after 15 minutes. A line «[staff] …»
-- is a staff reply and «[wait:N]» lets N minutes pass (eval.ts); one expectation per GUEST line. One audit batch.
do $team$
declare
  v_batch uuid := internal.begin_batch();
  v_sort integer;
begin
  perform set_config('app.actor', 'H6c — migration, Ahmed''s brief', true);
  v_sort := coalesce((select max(x.sort) + 1 from public.hub_test_items x), 0);
  insert into public.hub_test_items (key, unit_key, language, messages, expect, note, tags, added_from, sort)
  select e ->> 'id', e ->> 'unit', e ->> 'language', e -> 'messages', e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($team_bank$[{"id":"c047","unit":"airport-road","language":"ar","messages":["السلام عليكم، أبغى أكلم موظف","طيب عندكم مواقف؟","وكم سعر الإفطار؟"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","gap":false},{"outcome":"answer"},{"outcome":"answer"}]},"note":"a hand-off waiting for staff, then two sourced answers while it waits (Ahmed, 15 Nov 2026)","tags":["conversation","h6c","waiting"]},{"id":"c048","unit":"shafa-road","language":"ar","messages":["كم عدد الطوابق في المبنى؟","وهل يوجد مصعد للسطح؟","شكرا"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","gap":true},{"outcome":["handoff_add","answer"],"must_not_include":["سيكمل معك أحد أفراد فريقنا في هذه المحادثة"]},{"outcome":"reply"}]},"note":"a second thing it cannot answer joins the same hand-off: a short acknowledgement, never the fixed notice again","tags":["conversation","h6c","waiting"]},{"id":"c049","unit":"airport-road","language":"ar","messages":["أبغى أعدل تاريخ حجزي","[staff] أهلًا بك، نعم يمكن تعديل التاريخ. ما التاريخ الجديد الذي تريده؟","20 ديسمبر","[wait:16]","طيب عندكم مواقف؟"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","gap":false},{"outcome":"none"},{"outcome":"answer"}]},"note":"a staff reply → the assistant silent; 16 minutes of staff silence → the guest's next message resumes it","tags":["conversation","h6c","resume"]},{"id":"c050","unit":"shafa-road","language":"en","messages":["I'd like to speak to a person please","Is breakfast available?"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","gap":false},{"outcome":"answer"}]},"note":"waiting for staff, then a sourced answer (English)","tags":["conversation","h6c","waiting"]},{"id":"c051","unit":"airport-road","language":"ar","messages":["المكيف في غرفتي 205 خربان","[staff] تم إبلاغ الصيانة وسيصلك الفني خلال دقائق.","[wait:5]","متى يوصل؟"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","gap":false},{"outcome":"none"}]},"note":"a staff reply 5 minutes ago: the assistant stays silent (the branch's 15 minutes have not passed)","tags":["conversation","h6c","staff"]}]$team_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end;
$team$;

-- ───────────────────────────────────────────── 11. grants ─────────────────────────────────────────────
revoke execute on function internal.hub_slot_covers(public.hub_staff_slots, timestamptz), internal.hub_staff_lookup(text), internal.hub_staff_excluded(text),
  internal.hub_resume_minutes(text), internal.hub_human_phase(public.hub_conversations, public.hub_units, timestamptz), internal.hub_branch_channel(text),
  internal.hub_mask_phone(text), internal.hub_alertable(text), internal.hub_handoff_queue(uuid, text, timestamptz), internal.hub_kick_staff_sender(),
  internal.hub_report_data(date, timestamptz), internal.hub_report_tick(timestamptz) from public, anon, authenticated;
revoke execute on function public.hub_staff_sends_claim(integer, boolean), public.hub_staff_send_finish(uuid, text, text, text), public.hub_template_read_store(uuid, jsonb),
  public.hub_template_get(uuid, text, text), public.hub_report_email_claim(), public.hub_team_cron(timestamptz), public.hub_staff_chat_begin(jsonb),
  public.hub_staff_chat_finish(uuid, jsonb), public.hub_staff_number(text) from public, anon, authenticated;
grant execute on function public.hub_staff_sends_claim(integer, boolean), public.hub_staff_send_finish(uuid, text, text, text), public.hub_template_read_store(uuid, jsonb),
  public.hub_template_get(uuid, text, text), public.hub_report_email_claim(), public.hub_team_cron(timestamptz), public.hub_staff_chat_begin(jsonb),
  public.hub_staff_chat_finish(uuid, jsonb), public.hub_staff_number(text) to service_role;
revoke execute on function public.hub_team_get(), public.hub_staff_slot_save(jsonb), public.hub_staff_slot_delete(uuid), public.hub_team_branch_save(text, integer, integer),
  public.hub_report_recipient_save(jsonb), public.hub_report_recipient_delete(uuid), public.hub_report_config_save(text), public.hub_report_test(),
  public.hub_report_get(date), public.hub_alert_open(text), public.hub_handoff_seen(uuid) from public, anon;
grant execute on function public.hub_team_get(), public.hub_staff_slot_save(jsonb), public.hub_staff_slot_delete(uuid), public.hub_team_branch_save(text, integer, integer),
  public.hub_report_recipient_save(jsonb), public.hub_report_recipient_delete(uuid), public.hub_report_config_save(text), public.hub_report_test(),
  public.hub_report_get(date), public.hub_alert_open(text), public.hub_handoff_seen(uuid) to authenticated;
revoke all on public.hub_staff_slots, public.hub_team_branches, public.hub_report_recipients, public.hub_report_config, public.hub_handoffs,
  public.hub_staff_sends, public.hub_daily_reports, public.hub_staff_messages from anon, authenticated;

-- ───────────────────────────────────────────── 12. the clock ─────────────────────────────────────────────
select cron.schedule('hub-team', '* * * * *', 'select public.hub_team_cron()');
